    error = function(e) {
      cat("LOGGING FAILED:", ..., "\n")
    }
  )
}

## -----------------------------------------------------------------------------
## BLOCK 1B - CLEAN ADMINISTRATIVE MISSING VALUES
## -----------------------------------------------------------------------------

# Overview:
  # - Inspect variables 
  # - Identify administrative missing categories (e.g. "Missing", "Unknown")
  # - Convert these to system missing (NA)
  # - Drop unused factor levels
  # - Log changes for transparency and reproducibility

# Administrative missing values should not be treated as real categories in
# imputation models. Converting them to NA improves model stability.

## -----------------------------------------------------------------------------
## STEP 1: Inspect categorical levels (for logging)
## -----------------------------------------------------------------------------

catf('\n\nInspecting categorical variable levels (early stage)\n')

inspect_levels <- function(df) {
  
  log_lines <- c("\n--- VARIABLE LEVELS (PRE-CLEANING) ---")
  
  for (v in names(df)) {
    
    x <- df[[v]]
    
    if (is.factor(x) || is.character(x)) {
      
      levs <- unique(x)
      levs <- levs[!is.na(levs)]
      
      # Avoid extremely long lines
      if (length(levs) > 20) {
        levs_out <- paste0(
          paste(head(levs, 20), collapse = ", "),
          " ... [", length(levs), " levels]"
        )
      } else {
        levs_out <- paste(levs, collapse = ", ")
      }
      
      log_lines <- c(
        log_lines,
        paste0(v, ": ", levs_out)
      )
    }
  }
  
  catf(paste(log_lines, collapse = "\n"), "\n")
}

inspect_levels(alspacKids_ACE_data_2026)

## -----------------------------------------------------------------------------
## STEP 2: Define administrative missing patterns
## -----------------------------------------------------------------------------

admin_missing_patterns <- c(
  "Missing", "-1",
  "YE short", "Not in core sample",
  "HaB short", "Inconsistent data",
  "Not completed", "Missing/Not measured",
  "YHL", "At least one missing item", 
  "Birth outcome not known" , "unreasonable",
  "not known" , "missing"
)

## -----------------------------------------------------------------------------
## STEP 3: Replace admin missing values with NA
## -----------------------------------------------------------------------------

catf('\nCleaning administrative missing values (early stage)\n')

clean_admin_missing_all <- function(df) {
  
  for (v in names(df)) {
    
    x <- df[[v]]
    
    if (is.factor(x) || is.character(x)) {
      
      n_before <- sum(x %in% admin_missing_patterns, na.rm = TRUE)
      
      if (n_before > 0) {
        
        x[x %in% admin_missing_patterns] <- NA
        df[[v]] <- droplevels(as.factor(x))
        
        catf(paste0(v, ": ", n_before,
                    " admin values set to NA\n"))
      }
    }
  }
  
  return(df)
}

## Apply cleaning (ALL variables)
alspacKids_ACE_data_2026 <- clean_admin_missing_all(alspacKids_ACE_data_2026)

## -----------------------------------------------------------------------------
## STEP 4: Post-cleaning diagnostic summary
## -----------------------------------------------------------------------------

catf('\nSummary of missing values after early cleaning\n')

summarise_na_all <- function(df) {
  
  log_lines <- c("\n--- NA COUNTS (POST-CLEANING) ---")
  
  for (v in names(df)) {
    
    x <- df[[v]]
    
    if (is.factor(x) || is.character(x) || is.numeric(x)) {
      
      n_na <- sum(is.na(x))
      
      if (n_na > 0) {
        log_lines <- c(
          log_lines,
          paste0(v, ": NA = ", n_na)
        )
      }
    }
  }
  
  catf(paste(log_lines, collapse = "\n"), "\n")
}

summarise_na_all(alspacKids_ACE_data_2026)

summarise_na_all(alspacKids_ACE_data_2026)

## -----------------------------------------------------------------------------
## BLOCK 1C - FIX NUMERIC VARIABLES STORED AS FACTORS
## -----------------------------------------------------------------------------

# Overview:
  # - Detect numeric-like variables stored as factors/characters (e.g. EPDS, birth weight)
  # - ALSO handle variables with inequality coding (e.g. mz028b_org has "<16", ">43")
  # - Convert safely to numeric
  # - Log all conversions

catf('\n\nDetecting numeric variables stored as factors\n')

## -----------------------------------------------------------------------------
## STEP 1: Detect numeric-like variables
## -----------------------------------------------------------------------------

detect_numeric_like <- function(x) {
  
  if (!(is.factor(x) || is.character(x))) return(FALSE)
  
  vals <- unique(x)
  vals <- vals[!is.na(vals)]
  
  if (length(vals) == 0) return(FALSE)
  
  # Allow numeric OR inequality values
  is_num_like <- grepl("^[-]?[0-9.]+$", vals) |
    grepl("^<\\s*[0-9.]+$", vals) |
    grepl("^>\\s*[0-9.]+$", vals)
  
  return(mean(is_num_like) > 0.95 && length(vals) > 10)
}

## -----------------------------------------------------------------------------
## STEP 2: Convert safely
## -----------------------------------------------------------------------------

convert_numeric_factors <- function(df) {
  
  converted <- c()
  inequality_fixed <- c()
  
  for (v in names(df)) {
    
    if (detect_numeric_like(df[[v]])) {
      
      original <- as.character(df[[v]])
      
      # Handle inequality-coded values
      has_lower <- any(grepl("^<", original))
      has_upper <- any(grepl("^>", original))
      
      if (has_lower || has_upper) {
        
        # Extract numeric part
        num_vals <- suppressWarnings(as.numeric(gsub("[^0-9.]", "", original)))
        
        # Apply sensible recoding:
        # <X -> X - 1
        # >X -> X + 1
        
        original[grepl("^<", original)] <- 
          as.character(num_vals[grepl("^<", original)] - 1)
        
        original[grepl("^>", original)] <- 
          as.character(num_vals[grepl("^>", original)] + 1)
        
        inequality_fixed <- c(inequality_fixed, v)
      }
      
      # Convert to numeric
      new_var <- suppressWarnings(as.numeric(original))
      
      # Check how many NAs introduced
      na_diff <- sum(is.na(new_var)) - sum(is.na(df[[v]]))
      
      if (na_diff < 0.05 * length(new_var)) {
        df[[v]] <- new_var
        converted <- c(converted, v)
      }
    }
  }
  
  ## Logging
  if (length(converted) > 0) {
    catf('\nConverted to numeric:\n',
         paste(converted, collapse = ', '), '\n')
  } else {
    catf('\nNo misclassified numeric variables found\n')
  }
  
  if (length(inequality_fixed) > 0) {
    catf('\nHandled inequality-coded variables:\n',
         paste(unique(inequality_fixed), collapse = ', '), '\n')
  }
  
  return(df)
}

## Apply conversion
alspacKids_ACE_data_2026 <- convert_numeric_factors(alspacKids_ACE_data_2026)

## -----------------------------------------------------------------------------
## BLOCK 2 - SPLIT BY SEX (optional)
## -----------------------------------------------------------------------------

# Overview:
  # Split boys and girls for imputing separately by sex (optional)
  # Strongly recommend splitting by sex due to differences in ACE prevalence

alspacBoys_ACE_data_2026 <-
  droplevels(alspacKids_ACE_data_2026[
