alspacGirls_ACE_data_2026 <-
  droplevels(alspacKids_ACE_data_2026[
    grepl('Female', alspacKids_ACE_data_2026$kz021),
  ])

alspacKids_ACE_data_2026 <- droplevels(alspacKids_ACE_data_2026)

catf('\nSplit into boys (', nrow(alspacBoys_ACE_data_2026),
     ') and girls (', nrow(alspacGirls_ACE_data_2026), ')\n')

## -----------------------------------------------------------------------------
## BLOCK 3 - DETERMINE IMPUTATION VARIABLES (WITH DIAGNOSTICS)
## -----------------------------------------------------------------------------

# Overview:
  # Identify imputation variables (_org)
  # Detect categorical variables
  # Enforce >=50 per level rule (boys + girls separately)
  # Log WHICH variables fail and WHY
  # Decide: remove vs switch to binary

## -----------------------------------------------------------------------------
## Step 1: Identify imputation variables
## -----------------------------------------------------------------------------

imp_standard <- grep('org', names(alspacKids_ACE_data_2026), value = TRUE)

imp_factor <- imp_standard[
  !sapply(alspacKids_ACE_data_2026[, imp_standard],
          function(x) is.numeric(x) | is.integer(x))
]

catf('\nTotal imputation vars:', length(imp_standard),
     ' | categorical:', length(imp_factor), '\n')

## -----------------------------------------------------------------------------
## Step 2: Identify ACE-related categorical variables
## -----------------------------------------------------------------------------

imp_ACE <- imp_factor[
  gsub('_org', '', imp_factor) %in% adv_description$variable_unique
]

## -----------------------------------------------------------------------------
## Step 3: Identify variables with <50 per level 
## -----------------------------------------------------------------------------

# For imputation to work, auxiliary variables need to have at least 50 people in all levels.
# This needs to be true for boys and girls as these are imputed separately so:
# check for factor variables
# If your key analysis variable is excluded you can force include that variable

get_low_counts <- function(x) {
  tab <- table(factor(x))
  tab[tab < 50]
}

imp_ACE_less_n50 <- imp_ACE[
  sapply(alspacBoys_ACE_data_2026[, imp_ACE],
         function(x) any(table(factor(x)) < 50)) |
    sapply(alspacGirls_ACE_data_2026[, imp_ACE],
           function(x) any(table(factor(x)) < 50))
]

catf('\nACE vars with <50 per level:', length(imp_ACE_less_n50), '\n')

## -----------------------------------------------------------------------------
## Step 4: Detailed diagnostics
## -----------------------------------------------------------------------------

if (length(imp_ACE_less_n50) > 0) {
  
  log_lines <- c("\n--- LOW CELL COUNT DIAGNOSTICS ---")
  
  for (v in imp_ACE_less_n50) {
    
    log_lines <- c(log_lines, paste0("\nVariable: ", v))
    
    # Boys
    low_boys <- get_low_counts(alspacBoys_ACE_data_2026[[v]])
    if (length(low_boys) > 0) {
      log_lines <- c(
        log_lines,
        paste0("  Boys (<50): ",
               paste(names(low_boys), "=", low_boys, collapse = ", "))
      )
    }
    
    # Girls
    low_girls <- get_low_counts(alspacGirls_ACE_data_2026[[v]])
    if (length(low_girls) > 0) {
      log_lines <- c(
        log_lines,
        paste0("  Girls (<50): ",
               paste(names(low_girls), "=", low_girls, collapse = ", "))
      )
    }
  }
  
  # ✅ ONE write instead of many
  catf(paste(log_lines, collapse = "\n"), "\n")
}

## -----------------------------------------------------------------------------
## Step 5: Decide whether binary version can be used
## -----------------------------------------------------------------------------

imp_ACE_use_binary <- imp_ACE_less_n50[
  colSums(alspacBoys_ACE_data_2026[
    , gsub('_org', '', imp_ACE_less_n50)
  ], na.rm = TRUE) >= 50 &
    colSums(alspacGirls_ACE_data_2026[
      , gsub('_org', '', imp_ACE_less_n50)
    ], na.rm = TRUE) >= 50
]

catf('\nVariables switched to binary version:\n',
     ifelse(length(imp_ACE_use_binary) > 0,
            paste(imp_ACE_use_binary, collapse = ', '),
            'None'),
     '\n')

## -----------------------------------------------------------------------------
## Step 6: Identify variables to remove entirely
## -----------------------------------------------------------------------------

rm_imp <- imp_ACE_less_n50[
  !imp_ACE_less_n50 %in% imp_ACE_use_binary
]

catf('\nVariables removed completely:\n',
     ifelse(length(rm_imp) > 0,
            paste(rm_imp, collapse = ', '),
            'None'),
     '\n')

## -----------------------------------------------------------------------------
## Step 7: Apply decisions
## -----------------------------------------------------------------------------

# Remove unusable variables
if (length(rm_imp) > 0) {
  imp_standard <- imp_standard[!imp_standard %in% rm_imp]
}

# Replace with binary versions where appropriate
if (length(imp_ACE_use_binary) > 0) {
  imp_standard[imp_standard %in% imp_ACE_use_binary] <-
    gsub('_org', '', imp_standard[imp_standard %in% imp_ACE_use_binary])
}

catf('\nFinal number of imputation variables:', length(imp_standard), '\n')

## -----------------------------------------------------------------------------
## Step 8: Optional - save diagnostics table
## -----------------------------------------------------------------------------

low_count_summary <- data.frame()

if (length(imp_ACE_less_n50) > 0) {
  for (v in imp_ACE_less_n50) {
    
    boys <- table(factor(alspacBoys_ACE_data_2026[[v]]))
    girls <- table(factor(alspacGirls_ACE_data_2026[[v]]))
    
    temp <- data.frame(
      variable = v,
      level = c(names(boys), names(girls)),
      count = c(as.numeric(boys), as.numeric(girls)),
      group = rep(c("boys", "girls"),
                  times = c(length(boys), length(girls)))
    )
    
    low_count_summary <- rbind(low_count_summary, temp)
  }
  
  low_count_summary <- low_count_summary[
    low_count_summary$count < 50, ]
  
  write.csv(low_count_summary,
            paste0(loc_out, fileid_out, "_low_count_diagnostics.csv"),
            row.names = FALSE)
}

## Cleanup
rm(imp_ACE, imp_ACE_less_n50, imp_ACE_use_binary, imp_factor, rm_imp)

## -----------------------------------------------------------------------------
## BLOCK 4 - CREATE PREDICTOR MATRIX + METHODS 
## -----------------------------------------------------------------------------

# Overview:
  # Creating predictor matrix and imputation setup for ACE variables
  # This block prepares the data for multiple imputation using the `mice` package,
  # with careful handling of ACE variables.


## Key steps:

# 1. Define ACE variables
#    - Specify a list of ACE-related variables, including:
#     - Individual ACE exposures (e.g., abuse, neglect, household factors)
#     - Summary ACE scores (classic and extended)
#    - Create subsets:
#     - `ACEs`: component ACE variables (inputs to scores)
#     - `classicACEs`: subset corresponding to “classic” ACE definition

# 2. Match variables to dataset
#    - Use pattern matching (grep) to identify actual column names in the dataset.
#    - Allows flexibility if variables have suffixes or repeated measures.

# 3. Initialise mice setup
#    - Run `mice(..., maxit = 0)` to generate:
#    - Predictor matrix (defines which variables predict others)
#    - Method vector (defines how each variable is imputed)
#    - No imputation is performed at this stage.

# 4. Exclude non-informative variables
#    - Remove ID variables (e.g., `aln`, `qlet`) from:
#    - Being imputed
#    - Acting as predictors
#    - Optionally exclude sex (`kz021_org`) from imputation and prediction,
#      depending on analysis strategy (e.g. if stratifying by sex).

# 5. Handle ACE score variables
#    - Prevent ACE summary scores from being:
#    - Predicted by other variables
#    - Used as predictors


# 6. Passive imputation of ACE scores
#    - Define ACE scores as deterministic functions of their components:
#    - Classic ACE score = sum of classic ACE variables
#    - Extended ACE score = sum of extended ACE variables
#    - Implemented using `~I(...)` formulas in `mice`
#    - Ensures consistency: scores are always derived from imputed components
#      rather than imputed independently.

# 7. Output
#    - Final objects:
#    - `pred_mat`: predictor matrix used by mice
#    - `meth`: imputation methods (including passive formulas)
#    - These are later passed to `mice()` to perform the actual imputation.

## -----------------------------------------------------------------------------
## STEP 0: Log progress
## -----------------------------------------------------------------------------

catf('\n\n', Sys.time(), 'Creating predictor matrix\n')

## -----------------------------------------------------------------------------
## STEP 1: Define ACE variables
## -----------------------------------------------------------------------------

# All ACE-related measures (components + scores + related variables)
ACEmeasures <- c(
  "ACEscore_classic", 
  "physical_abuse", "sexual_abuse", "emotional_abuse", "emotional_neglect", 
  "bullying", "violence_between_parents", "substance_household", 
  "mental_health_problems_or_suicide", "parent_convicted_offence",
  "parental_separation", 
  "ACEscore_extended", 
  "social_class", "financial_difficulties", "neighbourhood", 
  "social_support_child", "social_support_parent", 
  "violence_between_child_and_partner", "physical_illness_child", 
  "physical_illness_parent", "parent_child_bond"
)

# ACE component variables (excluding summary scores)
ACEs <- ACEmeasures[c(2:11, 13:21)]

# Classic ACE subset
classicACEs <- ACEs[1:10]

## -----------------------------------------------------------------------------
## STEP 2: Match variables to dataset column names
## -----------------------------------------------------------------------------

ACEmeasures <- grep(
  paste0(ACEmeasures, collapse = '|'),
  names(alspacKids_ACE_data_2026),
  value = TRUE
)

ACEs <- grep(
  paste0(ACEs, collapse = '|'),
  names(alspacKids_ACE_data_2026),
  value = TRUE
)

classicACEs <- grep(
  paste0(classicACEs, collapse = '|'),
  names(alspacKids_ACE_data_2026),
  value = TRUE
)

# Inspect matches
length(ACEmeasures)
length(ACEs)
length(classicACEs)

## -----------------------------------------------------------------------------
## STEP 3: Initialise mice setup (no imputation yet)
## -----------------------------------------------------------------------------

ini <- mice(
  alspacKids_ACE_data_2026[
    , unique(c(imp_standard, ACEmeasures, "aln", "qlet"))
  ],
  maxit = 0,
  print = FALSE
)

# Include ID variables aln and qlet in the data but will be removed later,
# because don't want them to be used as predictors

# Extract predictor matrix and methods
pred_mat <- ini$predictorMatrix
meth     <- ini$method

## -----------------------------------------------------------------------------
## STEP 4: Exclude non-informative variables (ID variables, optional sex)
## -----------------------------------------------------------------------------


# Exclude sex variable because imputation is done separately by sex
if ("kz021_org" %in% names(meth)) {
  pred_mat[, "kz021_org"] <- 0
  meth["kz021_org"] <- ""
}

## Remove ID variables from imputation and prediction

id_vars <- c("aln", "qlet")

for (v in id_vars) {
  if (v %in% names(meth)) {
    meth[v] <- ""
  }
  if (v %in% colnames(pred_mat)) {
    pred_mat[, v] <- 0
  }
  if (v %in% rownames(pred_mat)) {
    pred_mat[v, ] <- 0
  }
}

## -----------------------------------------------------------------------------
## STEP 5: Prevent ACE score variables from acting as predictors
## -----------------------------------------------------------------------------

# Remove all ACE score variables from predictor roles
pred_mat[, grep("^ACE", colnames(pred_mat))] <- 0
pred_mat[grep("^ACE", rownames(pred_mat)), ] <- 0

## -----------------------------------------------------------------------------
## STEP 6: Define passive imputation for ACE scores
## -----------------------------------------------------------------------------

# NOTE:
# The previous version of code used as.integer() to convert ACE components prior to 
# summation. However, this can produce incorrect values if any ACE variables are 
# stored as factors, as as.integer(factor) returns underlying level codes (e.g. 
# 1, 2) rather than the intended binary values (0, 1). 

# Using as.numeric() is safer in this context because ACE variables are enforced 
# as logical (TRUE/FALSE) before imputation, and as.numeric() correctly maps:
#   TRUE  = 1
#   FALSE = 0
# This ensures that ACE scores are calculated correctly as the sum of binary 
# exposures during passive imputation.

meth[grep('ACEscore_extended_', names(meth), value = TRUE)] <-
  paste0('~I(', paste0('as.numeric(', ACEs, ')', collapse = '+'), ')')

meth[grep('ACEscore_classic_', names(meth), value = TRUE)] <- 
  paste0('~I(', paste0('as.numeric(', classicACEs, ')', collapse = '+'), ')')

## -----------------------------------------------------------------------------
## STEP 7: Finalise setup
## -----------------------------------------------------------------------------

# Outputs:
# pred_mat -> predictor matrix for mice
# meth     -> imputation methods (incl. passive ACE scores)

# Save both 
write.csv(pred_mat, "pred_mat.csv")
write.csv(meth, "meth.csv")

# Inspect meth carefully:
# All binary ACEs should use logreg
# All numeric variables should use pmm
# All categorical variables should use polyreg or other appropriate methods
# ACE score variables should use passive imputation formula, 
# which recalculates scores at each iteration as the sum of components. 

## Diagnostics (predictor matrix structure)

catf('\nPredictor matrix diagnostics:\n')

catf(paste0('Number of variables (meth): ', length(meth), '\n'))
catf(paste0('Predictor matrix dimensions: ',
            paste(dim(pred_mat), collapse = ' x '), '\n'))

catf('\nNumber of predictors per variable:\n')
catf(paste(capture.output(table(rowSums(pred_mat))), collapse = '\n'), '\n')

catf('\nVariables with no predictors:\n')

zero_preds <- names(which(rowSums(pred_mat) == 0))

if (length(zero_preds) == 0) {
  catf('None\n')
} else {
  catf(paste(zero_preds, collapse = ', '), '\n')
}

catf('\nPredictor matrix and methods created\n')

## -----------------------------------------------------------------------------
## BLOCK 5 - IMPUTATION 
## -----------------------------------------------------------------------------

# RECOMMEND using HPC

# Overview:
  # This block performs multiple imputation of missing data using the `mice`
  # package, with imputations conducted separately for males and females.

# Key steps:
# 1. Setup and logging
#    - Print timestamps to track progress during execution.
#    - Load the `mice` package for multiple imputation.

# 2. Prepare data for imputation
#    - Define a helper function (`construct.dat.for.mice`) to:
#    - Align dataset columns with the predictor matrix
#    - Ensure consistent variable ordering
#    - Convert logical variables to factors (required by `mice`)

# 3. Define imputation parameters
#    - Set:
#    - `m`: number of imputed datasets (e.g., 90)
#    - `maxit`: number of iterations per imputation (e.g., 30)

# 4. Construct analysis dataset
#    - Subset and reorder the original dataset to include only variables used
#      in the imputation model (based on the predictor matrix).


# 5. Optional test run
#    - A small test imputation (e.g., m = 5, maxit = 5) can be run to:
#    - Verify that the imputation model executes correctly
#    - Identify errors before running computationally intensive jobs
#    - Calculate time it will take to run FULL model

# 6. Run imputations
#    - Perform multiple imputation separately for males and females using:
#    - Predefined predictor matrix (`pred_mat`)
#    - Imputation methods (`meth`), including passive imputation for ACE scores
#    - Progress is printed and logged to an output file (via `sink()`),
#      enabling monitoring when running on a HPC.

# 8. Output
#    - Two `mids` objects are created:
#      - `imp_male`: imputed datasets for males
#      - `imp_female`: imputed datasets for females


catf('\n\n', Sys.time(), 'Code block 5: Imputation\n')

library(mice)

## -----------------------------------------------------------------------------
## Helper: align data with predictor matrix + fix logicals
## -----------------------------------------------------------------------------

# Force ACE scores to NA so passive imputation (~I(...)) is used;
# otherwise mice skips them 
alspacKids_ACE_data_2026$ACEscore_classic_0_16yrs  <- NA_real_
alspacKids_ACE_data_2026$ACEscore_extended_0_16yrs <- NA_real_

alspacBoys_ACE_data_2026$ACEscore_classic_0_16yrs  <- NA_real_
alspacBoys_ACE_data_2026$ACEscore_extended_0_16yrs <- NA_real_

alspacGirls_ACE_data_2026$ACEscore_classic_0_16yrs  <- NA_real_
alspacGirls_ACE_data_2026$ACEscore_extended_0_16yrs <- NA_real_

# NOTE:
# In the previous version, all logical variables were converted to factors 
# prior to imputation. However, this caused issues for ACE variables used in 
# passive imputation of ACE scores.
#
# Specifically, when ACE variables are stored as factors, subsequent conversion 
# using as.integer() (in the passive imputation formula) returns underlying 
# factor level codes (e.g. 1, 2) rather than the intended binary values (0, 1). 
# This leads to inflated and incorrect ACE scores.
#
# To resolve this, we now explicitly convert ACE variables back to logical after 
# the general factor conversion step. This ensures that:

#  TRUE = 1
#  FALSE = 0
# when used in passive imputation with as.numeric().
#
# This guarantees that ACE scores are correctly calculated as the sum of binary 
# exposures at each iteration.

construct.dat.for.mice <- function(dat, pred_mat) {
  idx <- match(rownames(pred_mat), names(dat))
  dat <- dat[, idx]
  
  # Convert all logicals to factors
  
  for (i in which(sapply(dat, is.logical))) {
    dat[[i]] <- as.factor(dat[[i]])
  }
  
  # ✅ FORCE ACE variables back to logical
  for (v in ACEs) {
    if (v %in% names(dat)) {
      dat[[v]] <- as.logical(as.character(dat[[v]]))
    }
  }
  
  dat
}

