  dat,
  m = m_test,
  maxit = maxit_test,
  print = TRUE,
  method = meth,
  predictorMatrix = pred_mat,
  seed = 140817
)

# Record end time
t2 <- Sys.time()

# Calculate elapsed runtime in minutes
