## -----------------------------------------------------------------------------
## Estimate full model runtime
## -----------------------------------------------------------------------------

# Explanation:
# The total computational effort is approximately proportional to:
#     m X maxit
#
# So we calculate a scaling factor:
#     (full workload) / (test workload)

scaling_factor <- (m_full * maxit_full) / (m_test * maxit_test)

catf(paste0(
  '\nScaling factor (full / test workload): ',
  scaling_factor, '\n'
))

# Multiply observed test runtime by scaling factor to estimate full runtime
est_boys  <- time_boys  * scaling_factor
est_girls <- time_girls * scaling_factor

# Convert minutes -> hours for readability
