library(openxlsx)

create_missingness_summary <- function(com_data) {
  
  # Original data only
  dat0 <- com_data[com_data$.imp == 0, ]
  
  # ✅ Correct denominator: number of individuals
  N <- length(unique(dat0$.id))
  
  # Remove technical columns
  dat_vars <- dat0[, !names(dat0) %in% c(".imp", ".id")]
  
  # Missing counts
  miss_n <- colSums(is.na(dat_vars))
  
  # Percent missing
  miss_pct <- (miss_n / N) * 100
  
  summary_df <- data.frame(
    variable = names(dat_vars),
    n_missing = miss_n,
    pct_missing = round(miss_pct, 2),
    sample_size = N,
    row.names = NULL
  )
  
  return(summary_df)
}

