create_imputation_summary <- function(imp_obj) {
  
  vars <- names(imp_obj$method)
  
  data.frame(
    original_var = vars,
    variable = gsub('_org|_dup', '', vars),
    type = sapply(imp_obj$data[, vars], function(x) {
      if (is.factor(x) | is.character(x)) {
        paste0("categorical (", length(unique(x)), " levels)")
      } else if (is.numeric(x) | is.integer(x)) {
        "continuous"
      } else if (is.logical(x)) {
        "binary"
      } else {
        class(x)
      }
    }),
    method = imp_obj$method,
    row.names = NULL
  )
}

