## STEP 5: FULL Rubin's rules pooled descriptive table (Table 1)
## -----------------------------------------------------------------------------

# AUTO-DETECT CATEGORICAL VARIABLES FROM MICE

get_categorical_vars <- function(imp_obj) {
  
  meth <- imp_obj$method
  meth <- meth[meth != ""]  # only imputed vars
  
  # Methods indicating categorical variables
  cat_vars <- names(meth)[meth %in% c("logreg", "polyreg", "polr")]
  
  # Also include factors/characters from original data
  data_types <- sapply(imp_obj$data, class)
  factor_vars <- names(data_types)[data_types %in% c("factor", "character")]
  
  categorical_vars <- unique(c(cat_vars, factor_vars))
  
  return(categorical_vars)
}

# RUBIN'S RULES FUNCTION

pool_variable <- function(values_list, type = "continuous") {
  
  m <- length(values_list)
  means <- sapply(values_list, mean, na.rm = TRUE)
  
  if (type == "continuous") {
    
    # Correct variance of the MEAN
    vars <- sapply(values_list, function(x) {
      var(x, na.rm = TRUE) / sum(!is.na(x))
    })
    
  } else if (type == "proportion") {
    
    vars <- sapply(values_list, function(x) {
      p <- mean(x, na.rm = TRUE)
      n <- sum(!is.na(x))
      (p * (1 - p)) / n
    })
  }
  
  Q_bar <- mean(means)
  U_bar <- mean(vars)
  B     <- var(means)
  
  T_var <- U_bar + (1 + 1/m) * B
  SE    <- sqrt(T_var)
  
  lower <- Q_bar - 1.96 * SE
  upper <- Q_bar + 1.96 * SE
  
  if (type == "proportion") {
    lower <- max(0, lower)
    upper <- min(1, upper)
  }
  
  return(c(est = Q_bar, se = SE, lci = lower, uci = upper))
}

# TABLE 1 FUNCTION

create_table1 <- function(com_all, categorical_vars) {
  
  # ✅ exclude original data (.imp = 0)
  imp_ids <- sort(unique(com_all$.imp))
  imp_ids <- imp_ids[imp_ids != 0]
  
  vars <- setdiff(names(com_all), c(".imp", ".id"))
  results <- list()
  
  for (v in vars) {
    
    dat_list <- lapply(imp_ids, function(i) {
      com_all[com_all$.imp == i, v]
    })
    
    # use mice-derived classification
    is_continuous <- !(v %in% categorical_vars)
    
    # ----------------------
    # CONTINUOUS VARIABLES
    # ----------------------
    if (is_continuous) {
      
      pooled <- pool_variable(dat_list, type = "continuous")
      
      results[[v]] <- data.frame(
        variable = v,
        level = NA,
        type = "continuous",
        estimate = pooled["est"],
        se = pooled["se"],
        lci = pooled["lci"],
        uci = pooled["uci"]
      )
      
    } else {
      
      # ----------------------
      # CATEGORICAL VARIABLES
      # ----------------------
      
      levels_all <- unique(na.omit(unlist(
        lapply(dat_list, function(x) as.character(x))
      )))
      
      for (lvl in levels_all) {
        
        bin_list <- lapply(dat_list, function(x) {
          as.numeric(as.character(x) == lvl)
        })
        
        pooled <- pool_variable(bin_list, type = "proportion")
        
        results[[paste0(v, "_", lvl)]] <- data.frame(
          variable = v,
          level = lvl,
          type = "categorical",
          estimate = pooled["est"] * 100,
          se = pooled["se"] * 100,
          lci = pooled["lci"] * 100,
          uci = pooled["uci"] * 100
        )
      }
    }
  }
  
  final_df <- do.call(rbind, results)
  
  final_df$estimate <- round(final_df$estimate, 2)
  final_df$se       <- round(final_df$se, 2)
  final_df$lci      <- round(final_df$lci, 2)
  final_df$uci      <- round(final_df$uci, 2)
  
  return(final_df)
}

# GENERATE TABLES

categorical_vars <- get_categorical_vars(imp_boys_test)

table1_boys  <- create_table1(boys_long, categorical_vars)
table1_girls <- create_table1(girls_long, categorical_vars)
table1_all   <- create_table1(com_all, categorical_vars)

